                data.closeLines = BuildStage05Close();
                break;
            case 6:
                data.openLines = BuildStage06Open();
                data.closeLines = BuildStage06Close();
                break;
            case 7:
                data.openLines = BuildStage07Open();
                data.closeLines = BuildStage07Close();
                break;
            case 8:
                data.openLines = BuildStage08Open();
                data.closeLines = BuildStage08Close();
                break;
            case 9:
                data.openLines = BuildStage09Open();
                data.closeLines = BuildStage09Close();
                break;
            case 10:
                data.openLines = BuildStage10Open();
                data.closeLines = BuildStage10Close();
                break;
            case 11:
                data.openLines = BuildStage11Open();
                data.closeLines = BuildStage11Close();
                break;
            case 12:
                data.openLines = BuildStage12Open();
                data.closeLines = BuildStage12Close();
                break;
            case 13:
                data.openLines = BuildStage13Open();
                data.closeLines = BuildStage13Close();
                break;
            case 14:
                data.openLines = BuildStage14Open();
                data.closeLines = BuildStage14Close();
                break;
            case 15:
                data.openLines = BuildStage15Open();
                data.closeLines = BuildStage15Close();
                break;
            case 16:
                data.openLines = BuildStage16Open();
                data.closeLines = BuildStage16Close();
                break;
            case 17:
                data.openLines = BuildStage17Open();
                data.closeLines = BuildStage17Close();
                break;
            case 18:
                data.openLines = BuildStage18Open();
                data.closeLines = BuildStage18Close();
                break;
            case 19:
                data.openLines = BuildStage19Open();
                data.closeLines = BuildStage19Close();
                break;
            case 20:
                data.openLines = BuildStage20Open();
                data.closeLines = BuildStage20Close();
                break;
            case 21:
                data.openLines = BuildStage21Open();
                data.closeLines = BuildStage21Close();
                break;
            case 22:
                data.openLines = BuildStage22Open();
                data.closeLines = BuildStage22Close();
                break;
            case 23:
                data.openLines = BuildStage23Open();
                data.closeLines = BuildStage23Close();
                break;
            case 24:
                data.openLines = BuildStage24Open();
                data.closeLines = BuildStage24Close();
                break;
            case 25:
                data.openLines = BuildStage25Open();
                data.closeLines = BuildStage25Close();
                break;
            case 26:
                data.openLines = BuildStage26Open();
                data.closeLines = BuildStage26Close();
                break;
            case 27:
                data.openLines = BuildStage27Open();
                data.closeLines = BuildStage27Close();
                break;
            case 28:
                data.openLines = BuildStage28Open();
                data.closeLines = BuildStage28Close();
                break;
            case 29:
                data.openLines = BuildStage29Open();
                data.closeLines = BuildStage29Close();
                break;
            case 30:
                data.openLines = BuildStage30Open();
                data.closeLines = BuildStage30Close();
                break;
            case 31:
                data.openLines = BuildStage31Open();
